/* JSON adapter registry: never calls a network transport. */
(function(){
'use strict';
const handlers=new Map();const history=[];
window.TrainingBackend={
 register(name,handler){if(!['fleet','denso','crobotp'].includes(name)||typeof handler!=='function')throw Error('Invalid offline adapter');handlers.set(name,handler);},
 async request(req){
  const ctx=window.TrainingModel;
  if(!ctx||!req||typeof req.path!=='string'||!req.path.startsWith('/')||req.path.startsWith('//'))return {status:400,payload:{ok:false,error:'Invalid offline request'}};
  req.path=req.path.replace(/^\/(?:denso|crobotp)(?=\/api\/)/,'').replace(/^\/robot\/\d+(?=\/api\/)/,'');const robot=Number(req.robot)||1;if(!ctx.state.robots[robot])return {status:400,payload:{ok:false,error:'Unknown training robot'}};
  ctx.state.robot=robot;
  req.query=req.query instanceof URLSearchParams?req.query:new URLSearchParams(req.query||'');req.body=req.body&&typeof req.body==='object'?req.body:{};
  const name=req.family||'fleet',handler=handlers.get(['/api/alerts','/api/robot-calls','/api/fleet','/api/program-catalog'].includes(req.path)?'fleet':name);
  if(!handler)return {status:503,payload:{ok:false,error:'Offline adapter is unavailable'}};
  try{const before=ctx.state.robots[robot].revision;let value;for(const hook of [window.NativeHandoverHandler,window.NativePresetHandler,window.NativeSharedHandler]){if(hook){value=await hook(req,ctx);if(value!==undefined)break;}}if(value===undefined)value=await handler(req,ctx);window.NativePresetAfterMutation?.(req,ctx,value,before);if(value===undefined||value===null)return {status:404,payload:{ok:false,error:'This endpoint is not available in offline practice'}};
   const result=value.status&&value.payload?value:{status:200,payload:value};history.push({family:name,robot,path:req.path,method:req.method,status:result.status});if(history.length>400)history.shift();return result;
  }catch(error){history.push({family:name,robot,path:req.path,method:req.method,status:400,error:String(error.message||error)});return {status:400,payload:{ok:false,error:String(error.message||error)}};}
 },getHistory:()=>history.slice(),getFamilies:()=>[...handlers.keys()]
};
})();

