  const t=Date.parse(b.occurred_at);if(!Number.isFinite(t))throw Error('วันที่ไม่ถูกต้อง');
  const local=new Date(t+7*3600000),year=local.getUTCFullYear();if(year<2000||year>2100)throw Error('วันที่ไม่ถูกต้อง');
  const occurred_at=local.toISOString().slice(0,16)+'+07:00';
