  if(b.images!==undefined&&(!Array.isArray(b.images)||b.images.length))throw Error('แบบฝึกออฟไลน์นี้ไม่รองรับแนบภาพ ยังไม่มีภาพถูกส่งหรือบันทึก');
  return {message:required(b.message,'Note',4000),robots:[...new Set(b.robots)].sort((a,b)=>a-b),occurred_at,shift:b.shift,shift_date:local.toISOString().slice(0,10),images:[]};
