    if(!['all','pending','acknowledged','archived'].includes(mode)||!Number.isInteger(offset)||offset<0||(robot!==null&&(!Number.isInteger(robot)||robot<1||robot>11)))return fail('ตัวกรองไม่ถูกต้อง');
