(()=>{'use strict';
const stage=document.querySelector('.native-practice'),bar=stage?.querySelector('.native-practice-bar'),frame=document.getElementById('actual-training-frame'),nav=document.querySelector('nav[aria-label="Manual"]');if(!stage||!bar||!frame)return;
const fold=document.createElement('details');fold.className='native-practice-help-fold';const summary=document.createElement('summary');summary.textContent='ข้อมูลแบบฝึก / Training details';fold.append(summary);[...bar.querySelectorAll('.native-practice-help')].forEach(x=>fold.append(x));bar.append(fold);
const home=document.getElementById('training-home');const row=home?.parentElement;if(row)row.classList.add('native-stage-buttons');
const open=document.createElement('button');open.type='button';open.className='native-stage-open';open.textContent='เต็มหน้าจอ / Expand';open.setAttribute('aria-controls','actual-training-frame');
const back=document.createElement('button');back.type='button';back.className='native-stage-back';back.textContent='← คู่มือ / Manual';back.setAttribute('aria-label','กลับไปอ่านคู่มือ / Return to manual');(row||bar).prepend(back);(row||bar).append(open);
let priorFocus=null,scrollY=0,inertSaved=[];function enter(){if(stage.classList.contains('native-focus'))return;priorFocus=document.activeElement;scrollY=window.scrollY;stage.classList.add('native-focus');stage.setAttribute('role','dialog');stage.setAttribute('aria-modal','true');const candidates=[...document.body.children].filter(x=>x.tagName!=='MAIN'&&!['SCRIPT','STYLE'].includes(x.tagName));const main=stage.closest('main');if(main)candidates.push(...[...main.children].filter(x=>!x.contains(stage)));inertSaved=candidates.map(x=>[x,x.inert]);inertSaved.forEach(([x])=>x.inert=true);document.body.classList.add('native-stage-active');open.setAttribute('aria-expanded','true');back.focus({preventScroll:true})}function leave(){if(!stage.classList.contains('native-focus'))return;stage.classList.remove('native-focus');stage.removeAttribute('role');stage.removeAttribute('aria-modal');inertSaved.forEach(([x,value])=>x.inert=value);inertSaved=[];document.body.classList.remove('native-stage-active');open.setAttribute('aria-expanded','false');measure();window.scrollTo(0,scrollY);priorFocus?.focus?.({preventScroll:true})}open.onclick=enter;back.onclick=leave;
document.addEventListener('click',e=>{const a=e.target.closest('a[href="#training"]');if(a&&window.matchMedia('(max-width:700px), (pointer:coarse) and (max-height:500px)').matches){e.preventDefault();enter()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.ownerDocument===document)leave()});
function measure(){if(nav&&!document.body.classList.contains('native-stage-active'))document.documentElement.style.setProperty('--manual-nav-height',Math.ceil(nav.getBoundingClientRect().height)+'px')}if(nav&&typeof ResizeObserver!=='undefined')new ResizeObserver(measure).observe(nav);window.addEventListener('resize',measure);measure();window.manualMobileStage={enter,leave};
})();
